def bcrypt(cost, salt, password):
    state = eks_blowfish_setup(cost, salt, password)
    ctext = 'OrpheanBeholderScryDoubt'  # 192비트 상수
    for _ in range(64):
        ctext = encrypt_ecb(state, ctext)
    return encode(cost, salt, ctext)

def eks_blowfish_setup(cost, salt, key):
    state = initial_state()  # π 소수부로 P배열·S박스 초기화
    state = expand_key(state, salt, key)
    for _ in range(2 ** cost):  # 비용 지수만큼 키 스트레칭
        state = expand_key(state, 0, key)
        state = expand_key(state, 0, salt)
    return state
